<section class="card"><h2>Linked system account</h2><?php if($staff['user_id']):$linked=access_service()->repo->user((int)$staff['user_id']);?><p>User #<?=(int)$staff['user_id']?> · <?=access_h($linked['name'] ?? '')?> · <?=access_h($linked['email'] ?? '')?> · <?=!empty($linked['active'])?'Active':'Inactive'?></p><p class="muted">The original account identity, password, roles and historical attribution are retained. Account activation and role changes remain in <a href="<?=access_h(access_url('users.php'))?>">System access management</a>.</p><?php else:?><h3>Link an existing user</h3><form method="post"><?php hr_fields('link_user',$id,$version);?><label class="hr-field">Existing user account *<select name="user_id" required><option value="">Choose an account after confirming its owner</option><?php foreach($candidates as $candidate):?><option value="<?=(int)$candidate['id']?>" <?=$candidate['staff_no']?'disabled':''?>>#<?=(int)$candidate['id']?> · <?=access_h($candidate['name'])?> · <?=access_h($candidate['email'])?> · <?=access_h($candidate['roles'])?> · <?=$candidate['active']?'Active':'Inactive'?><?=$candidate['staff_no']?' · Already linked to '.access_h($candidate['staff_no']):''?></option><?php endforeach?></select></label><label class="hr-check"><input type="checkbox" name="link_confirm" value="1" required> I verified this account belongs to this staff member.</label><?php hr_reason(true);?><p><button>Confirm account link</button></p></form><hr><h3>Issue a new account invitation</h3><p class="muted">Available after staff activation. The new account starts as a clerk. Any additional role assignment is an explicit access-management decision.</p><form method="post"><?php hr_fields('new_account',$id,$version);hr_reason(true);?><p><button>Approve access & issue invitation</button></p></form><?php endif?></section>
